css:
.p34-badged { display: inline-flex; align-items: center; gap: var(--s-2); padding-inline: var(--s-2); }
.p34-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -1); }
.p34-geartip { position: absolute; right: 0; top: calc(100% + var(--s-1)); z-index: 30; white-space: nowrap; }
.p34-tabtip { position: absolute; right: 0; bottom: calc(100% + var(--s-1)); z-index: 30; white-space: nowrap; }
.p34-tight { gap: var(--s-1); }
.p34-top { margin-bottom: var(--s-3); }
.p34-inline { display: inline-block; vertical-align: -0.2em; }
.p34-file { display: flex; justify-content: flex-end; margin-top: var(--s-1); }
.p34-file .badge { white-space: normal; overflow-wrap: anywhere; }
.msg .field__error { font-size: var(--fs-body); line-height: var(--lh-small); }
.p34-err { --frame-w: var(--w2); --frame-color: var(--terra); }
.p34-above { padding: 0 var(--s-2) var(--s-1); }
.p34-above .hint { width: 100%; }
.p34-tipline { display: flex; justify-content: flex-end; padding: 0 var(--s-2) var(--s-1); }
.p34-under { order: 3; padding: 0 var(--s-3) var(--s-2); font-size: var(--fs-small); line-height: var(--lh-small); }
.p34-under.field__error { padding-inline: var(--s-3); }

.p34-chips { display: flex; flex-wrap: wrap; gap: var(--s-2); padding: var(--s-1) var(--s-3); max-height: 7.5rem; overflow: auto; }
.p34-chip { display: inline-flex; align-items: center; gap: var(--s-2); max-width: 100%; min-height: 3rem; padding-inline-start: var(--s-1); border: var(--w1) solid var(--line); border-radius: var(--r); font-size: var(--fs-small); line-height: var(--lh-small); }
.p34-thumb { flex: none; display: grid; place-items: center; width: 2.5rem; height: 2.5rem; border: var(--w1) solid var(--line); border-radius: var(--r); background: var(--rule); }
.p34-thumb--doc { background: var(--white); }
.p34-nm { display: flex; min-width: 0; }
.p34-nm__a { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.p34-nm__b { flex: none; white-space: nowrap; }
.p34-wait { display: flex; align-items: center; gap: var(--s-2); }
.p34-histerr { display: grid; gap: var(--s-2); justify-items: start; }
.p34-rec { display: inline-block; width: 0.625rem; height: 0.625rem; border-radius: 50%; background: var(--ink); margin-inline-end: var(--s-2); }
.p35-form { display: grid; gap: var(--s-4); }
.p35-cols { display: grid; gap: var(--s-4); grid-template-columns: minmax(0, 1fr); align-items: start; }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p35-cols { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: var(--s-5); } }
.p35-col { display: grid; gap: var(--s-4); align-content: start; min-width: 0; }
.p35-sec { display: grid; gap: var(--s-2); min-width: 0; }
.p35-radios { display: grid; }
.p35-cap { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }
.p35-expl { display: block; font-size: var(--fs-small); line-height: var(--lh-small); color: var(--muted); }
.p35-cat { cursor: pointer; }
.p35-cat .rec__title { display: block; }
.p35-cat .rec__lead .check { min-height: var(--hit); }
.p35-hint { font-size: var(--fs-small); line-height: var(--lh-small); color: var(--muted); padding-inline-start: calc(1.125rem + var(--s-2)); margin-top: calc(var(--s-1) * -1); }
.p35-note { display: grid; gap: var(--s-1); padding: var(--s-2) 0; }
.p35-status { display: flex; align-items: center; gap: var(--s-2); padding: var(--s-4) 0; }
.p35-err { display: grid; gap: var(--s-3); justify-items: start; padding: var(--s-2) 0; }
.p35-err .banner { width: 100%; }
.p35-actions { position: sticky; bottom: 0; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--s-2); padding: var(--s-3); margin: var(--s-4) calc(var(--s-3) * -1) calc(var(--s-3) * -1); background: var(--white); border-top: var(--w1) solid var(--rule); z-index: 2; }
.p35-actions__right { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: var(--s-2); margin-inline-start: auto; }
.p35-applywrap { position: relative; display: inline-block; }
.p35-tip { position: absolute; right: 0; bottom: calc(100% + var(--s-2)); white-space: nowrap; z-index: 6; }
.p35-actions .btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p35-rules { display: grid; gap: var(--s-2); }
.p35-rule-over { min-height: 7rem; }
.p34-e { --frame-w: var(--w2); }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p34-end { justify-content: flex-end; } }
.p34-chip--err { border: var(--w2) solid var(--terra); padding-inline-end: var(--s-2); padding-block: var(--s-1); align-items: flex-start; }
.p34-chip--err .field__error { font-size: var(--fs-small); }
.p34-chipcol { display: grid; gap: var(--s-1); min-width: 0; }
.p34-wait--pad { padding: var(--s-3); }
